from pathlib import Path
import json,base64
from PIL import Image
P=Path(__file__).resolve().parent;ROOT=P.parents[2];R=P/'rig-render-6'
c=json.loads((P/'rig-continuity-contract.json').read_text());q=json.loads((P/'rig-continuity-qa.json').read_text());b=json.loads((R/'bindings.json').read_text());old=P.parent/'forward-pickup-v41';refs=json.loads((old/'approved-gif-reference.json').read_text())['references'];paths=set()
for f in c['frames']:paths.add(f['scene']['path']);paths.update(x['path'] for x in f['isolated'].values())
for r in refs:paths.update(f['decoded_path'] for f in r['frames'])
for i in range(8):paths.add(str((old/f'size-locked-review/{i:02}.png').relative_to(ROOT)))
urls={p:'data:image/png;base64,'+base64.b64encode((ROOT/p).read_bytes()).decode() for p in paths}
d=dict(contract=c,qa=q,rig=b,refs=refs,before=[str((old/f'size-locked-review/{i:02}.png').relative_to(ROOT)) for i in range(8)])
html=r'''<!doctype html><meta charset="utf-8"><title>v42 arm and size repair</title><style>body{background:#17232e;color:#edf4fc;font:16px system-ui;margin:24px}h1{font-size:24px}.row{display:flex;gap:12px;flex-wrap:wrap}figure{margin:0}canvas{width:272px;height:363px;border:1px solid #65788b;background:#2d3741}figcaption{max-width:272px;margin:8px 0}button,select,input{font:inherit;margin:6px 8px 6px 0}p{max-width:1120px;line-height:1.5}.notice{color:#ffc38f}table{border-collapse:collapse}td,th{padding:5px 12px;border-bottom:1px solid #475764;text-align:left}</style>
<p id="rejected" style="background:#812833;padding:12px;color:white">USER REJECTED — ผู้ใช้ปฏิเสธแขนชุดนี้ ห้ามนำผลตรวจความหนาไปอ้างว่ารูปทรงแขนผ่าน หรือใช้แขนนี้เป็นต้นแบบชุด 8 ทิศ</p><h1>แก้ขนาดแขนและความต่อเนื่อง — v42</h1><p>ภาพใหม่ใช้ rig ภายใน แล้วรวมเป็น body พร้อมชุด + หัวแยก ท่ายืนต้น/ท้าย399pxเท่ากัน ภาพตัวละครต้น/ท้ายตรงกันทุกพิกเซล เท้าไม่เลื่อนในหน้าต่างที่ตรวจ ความหนาวัสดุแขนและขาแกว่งไม่เกิน2px</p><p class="notice">ผ่านเฉพาะเกณฑ์ที่วัดได้ของ rig ชุดนี้ ยังไม่ใช่การอนุมัติงานภาพหรือ factory ทั้งหมด มุมหน้า/หลังต่างกันจึงยังพิสูจน์สัดส่วนกายวิภาคทุกส่วนไม่ได้ จุด rig เป็นจุดที่ใช้ประกอบภาพ ไม่ใช่ผลตรวจจับข้อต่อจากภาพ</p>
<div class="row"><figure><figcaption>GIF v39 ที่อนุมัติแล้ว / มุมหน้า</figcaption><canvas id="approved" width="384" height="512"></canvas></figure><figure><figcaption>v41 ที่ไม่ผ่าน / มุมหลัง</figcaption><canvas id="before" width="384" height="512"></canvas></figure><figure><figcaption>v42 / ผู้ใช้ปฏิเสธรูปทรงแขนแล้ว</figcaption><canvas id="candidate" width="384" height="512"></canvas></figure><figure><figcaption>ชิ้นที่เลือกใน rig / จุดวัดจากพิกเซลจริง</figcaption><canvas id="part" width="384" height="512"></canvas></figure></div>
<p><button id="play">เล่นหนึ่งครั้ง</button><input id="frame" type="range" min="0" max="7" value="0"><select id="clock"><option value="source">จังหวะ source GIF ที่อนุมัติ</option><option value="game">จังหวะ game GIF ที่อนุมัติ</option></select><label><input id="grid" type="checkbox">กริด20px</label><label><input id="rig" type="checkbox">rig ที่ใช้วาด</label><select id="partName"></select></p><p id="status"></p><p id="partStatus"></p><table><thead><tr><th>วัสดุที่วัด</th><th>ช่วงความหนาทั้ง8เฟรม</th><th>ความต่างสูงสุด</th></tr></thead><tbody id="widths"></tbody></table><p>จุดวัดรายส่วนใช้ชิ้นภาพที่เรารู้ตัวตนจาก rig จึงติดตามวัสดุเดิมได้ เมื่อเป็นภาพวาดใหม่ทั้งเฟรมหรือส่วนที่ถูกบังต้องตรวจใหม่ และห้ามถือว่าข้อต่อที่ซ่อนอยู่ถูกต้องโดยอัตโนมัติ</p>
<script>
const DATA=__DATA__,URLS=__URLS__,images={},canvases=Object.fromEntries(['approved','before','candidate','part'].map(k=>[k,document.getElementById(k)]));let ready=false,index=0,running=false,clock='source',start=0;const ref=()=>DATA.refs.find(r=>r.clock===clock),durations=()=>ref().frames.map(f=>f.duration_ms),selected=()=>document.getElementById('partName').value;
for(const name of Object.keys(DATA.qa.widths)){const o=document.createElement('option');o.value=o.textContent=name;document.getElementById('partName').append(o);const q=DATA.qa.widths[name],tr=document.createElement('tr');for(const x of [name,q.range_px.map(v=>v.toFixed(2)).join('–')+' px',(q.range_px[1]-q.range_px[0]).toFixed(2)+' px']){const td=document.createElement('td');td.textContent=x;tr.append(td)}document.getElementById('widths').append(tr)}
Promise.all(Object.entries(URLS).map(([k,v])=>new Promise(resolve=>{const im=new Image;im.onload=()=>{images[k]=im;resolve()};im.src=v}))).then(()=>{ready=true;draw()});
function draw(){if(!ready)return;const f=DATA.contract.frames[index],name=selected(),paths={approved:ref().frames[index].decoded_path,before:DATA.before[index],candidate:f.scene.path,part:f.isolated[name].path};for(const [k,cv] of Object.entries(canvases)){const x=cv.getContext('2d');x.clearRect(0,0,384,512);x.drawImage(images[paths[k]],0,0);if(document.getElementById('grid').checked){x.strokeStyle='#79a2bd55';for(let j=0;j<384;j+=20){x.beginPath();x.moveTo(j+.5,0);x.lineTo(j+.5,512);x.stroke()}for(let j=0;j<512;j+=20){x.beginPath();x.moveTo(0,j+.5);x.lineTo(384,j+.5);x.stroke()}}}
const o=DATA.qa.widths[name].observations[index],x=canvases.part.getContext('2d');x.strokeStyle='#6affbd';x.lineWidth=2;x.beginPath();x.moveTo(...o.endpoints[0]);x.lineTo(...o.endpoints[1]);x.stroke();x.fillStyle='white';for(const p of o.endpoints){x.beginPath();x.arc(...p,2,0,Math.PI*2);x.fill()}
if(document.getElementById('rig').checked){const x=canvases.candidate.getContext('2d'),p=DATA.rig.frames[index].source_points;for(const [s,color] of [['left','#ffb562'],['right','#55bdff']]){x.strokeStyle=color;x.lineWidth=2;for(const [a,b] of [['shoulder','elbow'],['elbow','wrist'],['wrist','palm'],['hip','knee'],['knee','ankle'],['ankle','toe']]){x.beginPath();x.moveTo(...p[s+'.'+a]);x.lineTo(...p[s+'.'+b]);x.stroke()}}}
document.getElementById('frame').value=index;document.getElementById('status').textContent='เฟรม '+(index+1)+'/8 · '+durations()[index]+' ms · เท้าสองข้างใช้ตำแหน่งเดิม · ขนาดต้น/ท้าย399px';document.getElementById('partStatus').textContent=name+' · วัดชิ้นภาพที่ตำแหน่งวัสดุเดิม: '+o.width_px.toFixed(2)+'px · การตรวจนี้ไม่ใช่การวัดปริมาตรหรือข้อต่อที่ถูกบัง';}
function select(i){running=false;index=Math.max(0,Math.min(7,i));draw()};function atTime(t){let n=0,sum=0;const ds=durations();while(n<7&&sum+ds[n]<=t){sum+=ds[n];n++}return n};function tick(t){if(!running)return;index=atTime(t-start);draw();if(t-start>=durations().reduce((a,b)=>a+b,0)){running=false;return}requestAnimationFrame(tick)}
document.getElementById('play').onclick=()=>{start=performance.now();index=0;running=true;requestAnimationFrame(tick)};document.getElementById('frame').oninput=e=>select(+e.target.value);document.getElementById('clock').onchange=e=>{clock=e.target.value;select(0)};for(const k of ['grid','rig','partName'])document.getElementById(k).onchange=draw;document.onkeydown=e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowRight')select(index+1);if(e.key==='ArrowLeft')select(index-1)};window.review={get ready(){return ready},get index(){return index},get running(){return running},get clock(){return clock},data:DATA,images,canvases,select,atTime};
</script>'''
(P/'review.html').write_text(html.replace('__DATA__',json.dumps(d,separators=(',',':'))).replace('__URLS__',json.dumps(urls,separators=(',',':'))))
# One static enlarged surface audit with actual endpoints and coordinate grid.
sheet=Image.new('RGBA',(1152,566),(45,55,65,255));from PIL import ImageDraw
draw=ImageDraw.Draw(sheet)
for j,i in enumerate([0,3,7]):
 sheet.alpha_composite(Image.open(R/f'full/{i:02}.png'),(j*384,26));draw.text((j*384+8,8),'v42 frame'+str(i+1)+' / authored visible surfaces',fill='white')
 for name,w in q['widths'].items():
  o=w['observations'][i];pts=[(p[0]+j*384,p[1]+26) for p in o['endpoints']];draw.line(pts,fill=(100,255,180),width=2)
draw.text((8,547),'Same authored materials: arm/shin width variation <=2px; full neutral0/7 pixels identical. Hidden anatomy remains unproved.',fill='white');sheet.convert('RGB').save(P/'rig-surface-review.png')
print('Offline source/old/new/isolated material reviewer built')
